def compute(vars):
    total = vars["v2"]
    if total == 0:
        return None

    ratio = vars["v1"] / total * 100

    return {
        "value": ratio,
        "trace": {
            "numerator": vars["v1"],
            "denominator": total,
            "ratio": ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
